20	import * as zrUtil from 'zrender/src/core/util';
21	import LinearGradient, { LinearGradientObject } from 'zrender/src/graphic/LinearGradient';
22	import * as eventTool from 'zrender/src/core/event';
23	import VisualMapView from './VisualMapView';
24	import * as graphic from '../../util/graphic';
25	import * as numberUtil from '../../util/number';
26	import sliderMove from '../helper/sliderMove';
27	import * as helper from './helper';
28	import * as modelUtil from '../../util/model';
29	import VisualMapModel from './VisualMapModel';
30	import ContinuousModel from './ContinuousModel';
31	import GlobalModel from '../../model/Global';
32	import ExtensionAPI from '../../core/ExtensionAPI';
33	import Element, { ElementEvent } from 'zrender/src/Element';
34	import { TextVerticalAlign, TextAlign } from 'zrender/src/core/types';
35	import { ColorString, Payload } from '../../util/types';
36	import { parsePercent } from 'zrender/src/contain/text';
37	import { setAsHighDownDispatcher } from '../../util/states';
38	import { createSymbol } from '../../util/symbol';
39	import ZRImage from 'zrender/src/graphic/Image';
40	import { ECData, getECData } from '../../util/innerStore';
41	import { createTextStyle } from '../../label/labelStyle';
42	import { findEventDispatcher } from '../../util/event';
43	
44	const linearMap = numberUtil.linearMap;
45	const each = zrUtil.each;
46	const mathMin = Math.min;
47	const mathMax = Math.max;
48	
49	// Arbitrary value
50	const HOVER_LINK_SIZE = 12;
51	const HOVER_LINK_OUT = 6;
52	
53	type Orient = VisualMapModel['option']['orient'];
54	
55	type ShapeStorage = {
56	    handleThumbs: graphic.Path[]
57	    handleLabelPoints: number[][]
58	    handleLabels: graphic.Text[]
59	
60	    inRange: graphic.Polygon
61	    outOfRange: graphic.Polygon
62	
63	    mainGroup: graphic.Group
64	
65	    indicator: graphic.Path
66	    indicatorLabel: graphic.Text
67	    indicatorLabelPoint: number[]
68	};
69	
70	type TargetDataIndices = ReturnType<ContinuousModel['findTargetDataIndices']>;
71	
72	type BarVisual = {
73	    barColor: LinearGradient,
74	    barPoints: number[][]
75	    handlesColor: ColorString[]
76	};
77	
78	type Direction = 'left' | 'right' | 'top' | 'bottom';
79	// Notice:
80	// Any "interval" should be by the order of [low, high].
81	// "handle0" (handleIndex === 0) maps to
82	// low data value: this._dataInterval[0] and has low coord.
83	// "handle1" (handleIndex === 1) maps to
84	// high data value: this._dataInterval[1] and has high coord.
85	// The logic of transform is implemented in this._createBarGroup.
86	
87	class ContinuousView extends VisualMapView {
88	    static type = 'visualMap.continuous';
89	    type = ContinuousView.type;
90	
91	    visualMapModel: ContinuousModel;
92	
93	    private _shapes = {} as ShapeStorage;
94	
95	    private _dataInterval: number[] = [];
96	
97	    private _handleEnds: number[] = [];
98	
99	    private _orient: Orient;
100	
101	    private _useHandle: boolean;
102	
103	    private _hoverLinkDataIndices: TargetDataIndices = [];
104	
105	    private _dragging: boolean;
106	
107	    private _hovering: boolean;
108	
109	    private _firstShowIndicator: boolean;
110	
111	    init(ecModel: GlobalModel, api: ExtensionAPI) {
112	        super.init(ecModel, api);
113	
114	        this._hoverLinkFromSeriesMouseOver = zrUtil.bind(this._hoverLinkFromSeriesMouseOver, this);
115	        this._hideIndicator = zrUtil.bind(this._hideIndicator, this);
116	    }
117	
118	    doRender(
119	        visualMapModel: ContinuousModel,
120	        ecModel: GlobalModel,
121	        api: ExtensionAPI,
122	        payload: {type: string, from: string}
123	    ) {
124	        if (!payload || payload.type !== 'selectDataRange' || payload.from !== this.uid) {
125	            this._buildView();
126	        }
127	    }
128	
129	    private _buildView() {
130	        this.group.removeAll();
131	
132	        const visualMapModel = this.visualMapModel;
133	        const thisGroup = this.group;
134	
135	        this._orient = visualMapModel.get('orient');
136	        this._useHandle = visualMapModel.get('calculable');
137	
138	        this._resetInterval();
139	
140	        this._renderBar(thisGroup);
141	
142	        const dataRangeText = visualMapModel.get('text');
143	        this._renderEndsText(thisGroup, dataRangeText, 0);
144	        this._renderEndsText(thisGroup, dataRangeText, 1);
145	
146	        // Do this for background size calculation.
147	        this._updateView(true);
148	
149	        // After updating view, inner shapes is built completely,
150	        // and then background can be rendered.
151	        this.renderBackground(thisGroup);
152	
153	        // Real update view
154	        this._updateView();
155	
156	        this._enableHoverLinkToSeries();
157	        this._enableHoverLinkFromSeries();
158	
159	        this.positionGroup(thisGroup);
160	    }
161	
162	    private _renderEndsText(group: graphic.Group, dataRangeText: string[], endsIndex?: 0 | 1) {
163	        if (!dataRangeText) {
164	            return;
165	        }
166	
167	        // Compatible with ec2, text[0] map to high value, text[1] map low value.
168	        let text = dataRangeText[1 - endsIndex];
169	        text = text != null ? text + '' : '';
170	
171	        const visualMapModel = this.visualMapModel;
172	        const textGap = visualMapModel.get('textGap');
173	        const itemSize = visualMapModel.itemSize;
174	
175	        const barGroup = this._shapes.mainGroup;
176	        const position = this._applyTransform(
177	            [
178	                itemSize[0] / 2,
179	                endsIndex === 0 ? -textGap : itemSize[1] + textGap
180	            ],
181	            barGroup
182	        ) as number[];
183	        const align = this._applyTransform(
184	            endsIndex === 0 ? 'bottom' : 'top',
185	            barGroup
186	        );
187	        const orient = this._orient;
188	        const textStyleModel = this.visualMapModel.textStyleModel;
189	
190	        this.group.add(new graphic.Text({
191	            style: createTextStyle(textStyleModel, {
192	                x: position[0],
193	                y: position[1],
194	                verticalAlign: textStyleModel.get('verticalAlign')
195	                    || (orient === 'horizontal' ? 'middle' : align as TextVerticalAlign),
196	                align: textStyleModel.get('align')
197	                    || (orient === 'horizontal' ? align as TextAlign : 'center'),
198	                text
199	            })
200	        }));
201	    }
202	
203	    private _renderBar(targetGroup: graphic.Group) {
204	        const visualMapModel = this.visualMapModel;
205	        const shapes = this._shapes;
206	        const itemSize = visualMapModel.itemSize;
207	        const orient = this._orient;
208	        const useHandle = this._useHandle;
209	        const itemAlign = helper.getItemAlign(visualMapModel, this.api, itemSize);
210	        const mainGroup = shapes.mainGroup = this._createBarGroup(itemAlign);
211	
212	        const gradientBarGroup = new graphic.Group();
213	        mainGroup.add(gradientBarGroup);
214	
215	        // Bar
216	        gradientBarGroup.add(shapes.outOfRange = createPolygon());
217	        gradientBarGroup.add(shapes.inRange = createPolygon(
218	            null,
219	            useHandle ? getCursor(this._orient) : null,
220	            zrUtil.bind(this._dragHandle, this, 'all', false),
221	            zrUtil.bind(this._dragHandle, this, 'all', true)
222	        ));
223	
224	        // A border radius clip.
225	        gradientBarGroup.setClipPath(new graphic.Rect({
226	            shape: {
227	                x: 0,
228	                y: 0,
229	                width: itemSize[0],
230	                height: itemSize[1],
231	                r: 3
232	            }
233	        }));
234	
235	        const textRect = visualMapModel.textStyleModel.getTextRect('国');
236	        const textSize = mathMax(textRect.width, textRect.height);
237	
238	        // Handle
239	        if (useHandle) {
240	            shapes.handleThumbs = [];
241	            shapes.handleLabels = [];
242	            shapes.handleLabelPoints = [];
243	
244	            this._createHandle(visualMapModel, mainGroup, 0, itemSize, textSize, orient);
245	            this._createHandle(visualMapModel, mainGroup, 1, itemSize, textSize, orient);
246	        }
247	
248	        this._createIndicator(visualMapModel, mainGroup, itemSize, textSize, orient);
249	
250	        targetGroup.add(mainGroup);
251	    }
252	
253	    private _createHandle(
254	        visualMapModel: ContinuousModel,
255	        mainGroup: graphic.Group,
256	        handleIndex: 0 | 1,
257	        itemSize: number[],
258	        textSize: number,
259	        orient: Orient
260	    ) {
261	        const onDrift = zrUtil.bind(this._dragHandle, this, handleIndex, false);
262	        const onDragEnd = zrUtil.bind(this._dragHandle, this, handleIndex, true);
263	        const handleSize = parsePercent(visualMapModel.get('handleSize'), itemSize[0]);
264	        const handleThumb = createSymbol(
265	            visualMapModel.get('handleIcon'),
266	            -handleSize / 2, -handleSize / 2, handleSize, handleSize,
267	            null, true
268	        );
269	        const cursor = getCursor(this._orient);
270	        handleThumb.attr({
271	            cursor: cursor,
272	            draggable: true,
273	            drift: onDrift,
274	            ondragend: onDragEnd,
275	            onmousemove(e) {
276	                eventTool.stop(e.event);
277	            }
278	        });
279	        handleThumb.x = itemSize[0] / 2;
280	
281	        handleThumb.useStyle(visualMapModel.getModel('handleStyle').getItemStyle());
282	        (handleThumb as graphic.Path).setStyle({
283	            strokeNoScale: true,
284	            strokeFirst: true
285	        });
286	        (handleThumb as graphic.Path).style.lineWidth *= 2;
287	
288	        handleThumb.ensureState('emphasis').style = visualMapModel.getModel(['emphasis', 'handleStyle']).getItemStyle();
289	        setAsHighDownDispatcher(handleThumb, true);
290	
291	        mainGroup.add(handleThumb);
292	
293	        // Text is always horizontal layout but should not be effected by
294	        // transform (orient/inverse). So label is built separately but not
295	        // use zrender/graphic/helper/RectText, and is located based on view
296	        // group (according to handleLabelPoint) but not barGroup.
297	        const textStyleModel = this.visualMapModel.textStyleModel;
298	        const handleLabel = new graphic.Text({
299	            cursor: cursor,
300	            draggable: true,
301	            drift: onDrift,
302	            onmousemove(e) {
303	                // For mobile device, prevent screen slider on the button.
304	                eventTool.stop(e.event);
305	            },
306	            ondragend: onDragEnd,
307	            style: createTextStyle(textStyleModel, {
308	                x: 0,
309	                y: 0,
310	                text: ''
311	            })
312	        });
313	        handleLabel.ensureState('blur').style = {
314	            opacity: 0.1
315	        };
316	        handleLabel.stateTransition = { duration: 200 };
317	
318	        this.group.add(handleLabel);
319	
320	        const handleLabelPoint = [handleSize, 0];
321	
322	        const shapes = this._shapes;
323	        shapes.handleThumbs[handleIndex] = handleThumb;
324	        shapes.handleLabelPoints[handleIndex] = handleLabelPoint;
325	        shapes.handleLabels[handleIndex] = handleLabel;
326	    }
327	
328	    private _createIndicator(
329	        visualMapModel: ContinuousModel,
330	        mainGroup: graphic.Group,
331	        itemSize: number[],
332	        textSize: number,
333	        orient: Orient
334	    ) {
335	        const scale = parsePercent(visualMapModel.get('indicatorSize'), itemSize[0]);
336	        const indicator = createSymbol(
337	            visualMapModel.get('indicatorIcon'),
338	            -scale / 2, -scale / 2, scale, scale,
339	            null, true
340	        );
341	        indicator.attr({
342	            cursor: 'move',
343	            invisible: true,
344	            silent: true,
345	            x: itemSize[0] / 2
346	        });
347	        const indicatorStyle = visualMapModel.getModel('indicatorStyle').getItemStyle();
348	        if (indicator instanceof ZRImage) {
349	            const pathStyle = indicator.style;
350	            indicator.useStyle(zrUtil.extend({
351	                // TODO other properties like x, y ?
352	                image: pathStyle.image,
353	                x: pathStyle.x, y: pathStyle.y,
354	                width: pathStyle.width, height: pathStyle.height
355	            }, indicatorStyle));
356	        }
357	        else {
358	            indicator.useStyle(indicatorStyle);
359	        }
360	
361	        mainGroup.add(indicator);
362	
363	        const textStyleModel = this.visualMapModel.textStyleModel;
364	        const indicatorLabel = new graphic.Text({
365	            silent: true,
366	            invisible: true,
367	            style: createTextStyle(textStyleModel, {
368	                x: 0,
369	                y: 0,
370	                text: ''
371	            })
372	        });
373	        this.group.add(indicatorLabel);
374	
375	        const indicatorLabelPoint = [
376	            (orient === 'horizontal' ? textSize / 2 : HOVER_LINK_OUT) + itemSize[0] / 2,
377	            0
378	        ];
379	
380	        const shapes = this._shapes;
381	        shapes.indicator = indicator;
382	        shapes.indicatorLabel = indicatorLabel;
383	        shapes.indicatorLabelPoint = indicatorLabelPoint;
384	
385	        this._firstShowIndicator = true;
386	    }
