430	    private _resetInterval() {
431	        const visualMapModel = this.visualMapModel;
432	
433	        const dataInterval = this._dataInterval = visualMapModel.getSelected();
434	        const dataExtent = visualMapModel.getExtent();
435	        const sizeExtent = [0, visualMapModel.itemSize[1]];
436	
437	        this._handleEnds = [
438	            linearMap(dataInterval[0], dataExtent, sizeExtent, true),
439	            linearMap(dataInterval[1], dataExtent, sizeExtent, true)
440	        ];
441	    }
