503	    private _createBarVisual(
504	        dataInterval: number[],
505	        dataExtent: number[],
506	        handleEnds: number[],
507	        forceState: ContinuousModel['stateList'][number]
508	    ): BarVisual {
509	        const opts = {
510	            forceState: forceState,
511	            convertOpacityToAlpha: true
512	        };
513	        const colorStops = this._makeColorGradient(dataInterval, opts);
514	
515	        const symbolSizes = [
516	            this.getControllerVisual(dataInterval[0], 'symbolSize', opts) as number,
517	            this.getControllerVisual(dataInterval[1], 'symbolSize', opts) as number
518	        ];
519	        const barPoints = this._createBarPoints(handleEnds, symbolSizes);
520	
521	        return {
522	            barColor: new LinearGradient(0, 0, 0, 1, colorStops),
523	            barPoints: barPoints,
524	            handlesColor: [
525	                colorStops[0].color,
526	                colorStops[colorStops.length - 1].color
527	            ]
528	        };
529	    }
530	
531	    private _makeColorGradient(
532	        dataInterval: number[],
533	        opts: {
534	            forceState?: ContinuousModel['stateList'][number]
535	            convertOpacityToAlpha?: boolean
536	        }
537	    ) {
538	        // Considering colorHue, which is not linear, so we have to sample
539	        // to calculate gradient color stops, but not only calculate head
540	        // and tail.
541	        const sampleNumber = 100; // Arbitrary value.
542	        const colorStops: LinearGradientObject['colorStops'] = [];
543	        const step = (dataInterval[1] - dataInterval[0]) / sampleNumber;
544	
545	        colorStops.push({
546	            color: this.getControllerVisual(dataInterval[0], 'color', opts) as ColorString,
547	            offset: 0
548	        });
549	
550	        for (let i = 1; i < sampleNumber; i++) {
551	            const currValue = dataInterval[0] + step * i;
552	            if (currValue > dataInterval[1]) {
553	                break;
554	            }
555	            colorStops.push({
556	                color: this.getControllerVisual(currValue, 'color', opts) as ColorString,
557	                offset: i / sampleNumber
558	            });
559	        }
560	
561	        colorStops.push({
562	            color: this.getControllerVisual(dataInterval[1], 'color', opts) as ColorString,
563	            offset: 1
564	        });
565	
566	        return colorStops;
567	    }
568	
569	    private _createBarPoints(handleEnds: number[], symbolSizes: number[]) {
570	        const itemSize = this.visualMapModel.itemSize;
571	
572	        return [
573	            [itemSize[0] - symbolSizes[0], handleEnds[0]],
574	            [itemSize[0], handleEnds[0]],
575	            [itemSize[0], handleEnds[1]],
576	            [itemSize[0] - symbolSizes[1], handleEnds[1]]
577	        ];
578	    }
579	
580	    private _createBarGroup(itemAlign: helper.ItemAlign) {
581	        const orient = this._orient;
582	        const inverse = this.visualMapModel.get('inverse');
583	
584	        return new graphic.Group(
585	            (orient === 'horizontal' && !inverse)
586	            ? {scaleX: itemAlign === 'bottom' ? 1 : -1, rotation: Math.PI / 2}
587	            : (orient === 'horizontal' && inverse)
588	            ? {scaleX: itemAlign === 'bottom' ? -1 : 1, rotation: -Math.PI / 2}
589	            : (orient === 'vertical' && !inverse)
590	            ? {scaleX: itemAlign === 'left' ? 1 : -1, scaleY: -1}
591	            : {scaleX: itemAlign === 'left' ? 1 : -1}
592	        );
593	    }
594	
595	    private _updateHandle(handleEnds: number[], visualInRange: BarVisual) {
596	        if (!this._useHandle) {
597	            return;
598	        }
599	
600	        const shapes = this._shapes;
601	        const visualMapModel = this.visualMapModel;
602	        const handleThumbs = shapes.handleThumbs;
603	        const handleLabels = shapes.handleLabels;
604	        const itemSize = visualMapModel.itemSize;
605	        const dataExtent = visualMapModel.getExtent();
606	        const align = this._applyTransform('left', shapes.mainGroup);
607	
608	        each([0, 1], function (handleIndex) {
609	            const handleThumb = handleThumbs[handleIndex];
610	            handleThumb.setStyle('fill', visualInRange.handlesColor[handleIndex]);
611	            handleThumb.y = handleEnds[handleIndex];
612	
613	            const val = linearMap(handleEnds[handleIndex], [0, itemSize[1]], dataExtent, true);
614	            const symbolSize = this.getControllerVisual(val, 'symbolSize') as number;
615	
616	            handleThumb.scaleX = handleThumb.scaleY = symbolSize / itemSize[0];
617	            handleThumb.x = itemSize[0] - symbolSize / 2;
618	
619	            // Update handle label position.
620	            const textPoint = graphic.applyTransform(
621	                shapes.handleLabelPoints[handleIndex],
622	                graphic.getTransform(handleThumb, this.group)
623	            );
624	
625	            if (this._orient === 'horizontal') {
626	                // If visualMap controls symbol size, an additional offset needs to be added to labels to avoid collision at minimum size.
627	                // Offset reaches value of 0 at "maximum" position, so maximum position is not altered at all.
628	                const minimumOffset = align === 'left' || align === 'top'
629	                    ? (itemSize[0] - symbolSize) / 2
630	                    : (itemSize[0] - symbolSize) / -2;
631	
632	                textPoint[1] += minimumOffset;
633	            }
634	
635	            handleLabels[handleIndex].setStyle({
636	                x: textPoint[0],
637	                y: textPoint[1],
638	                text: visualMapModel.formatValueText(this._dataInterval[handleIndex]),
639	                verticalAlign: 'middle',
640	                align: this._orient === 'vertical' ? this._applyTransform(
641	                    'left',
642	                    shapes.mainGroup
643	                ) as TextAlign : 'center'
644	            });
645	        }, this);
646	    }
647	
648	    private _showIndicator(
649	        cursorValue: number,
650	        textValue: number,
651	        rangeSymbol?: string,
652	        halfHoverLinkSize?: number
653	    ) {
654	        const visualMapModel = this.visualMapModel;
655	        const dataExtent = visualMapModel.getExtent();
656	        const itemSize = visualMapModel.itemSize;
657	        const sizeExtent = [0, itemSize[1]];
658	
659	        const shapes = this._shapes;
660	        const indicator = shapes.indicator;
661	        if (!indicator) {
662	            return;
663	        }
664	
665	        indicator.attr('invisible', false);
666	
667	        const opts = {convertOpacityToAlpha: true};
668	        const color = this.getControllerVisual(cursorValue, 'color', opts) as ColorString;
669	        const symbolSize = this.getControllerVisual(cursorValue, 'symbolSize') as number;
670	        const y = linearMap(cursorValue, dataExtent, sizeExtent, true);
671	        const x = itemSize[0] - symbolSize / 2;
672	
673	        const oldIndicatorPos = { x: indicator.x, y: indicator.y };
674	        // Update handle label position.
675	        indicator.y = y;
676	        indicator.x = x;
677	        const textPoint = graphic.applyTransform(
678	            shapes.indicatorLabelPoint,
679	            graphic.getTransform(indicator, this.group)
680	        );
681	
682	        const indicatorLabel = shapes.indicatorLabel;
683	        indicatorLabel.attr('invisible', false);
684	        const align = this._applyTransform('left', shapes.mainGroup);
685	        const orient = this._orient;
686	        const isHorizontal = orient === 'horizontal';
687	        indicatorLabel.setStyle({
688	            text: (rangeSymbol ? rangeSymbol : '') + visualMapModel.formatValueText(textValue),
689	            verticalAlign: isHorizontal ? align as TextVerticalAlign : 'middle',
690	            align: isHorizontal ? 'center' : align as TextAlign
691	        });
692	
693	        const indicatorNewProps = {
694	            x: x,
695	            y: y,
696	            style: {
697	                fill: color
698	            }
699	        };
700	        const labelNewProps = {
701	            style: {
702	                x: textPoint[0],
703	                y: textPoint[1]
704	            }
705	        };
706	
707	        if (visualMapModel.ecModel.isAnimationEnabled() && !this._firstShowIndicator) {
708	            const animationCfg = {
709	                duration: 100,
710	                easing: 'cubicInOut',
711	                additive: true
712	            } as const;
713	            indicator.x = oldIndicatorPos.x;
714	            indicator.y = oldIndicatorPos.y;
715	            indicator.animateTo(indicatorNewProps, animationCfg);
716	            indicatorLabel.animateTo(labelNewProps, animationCfg);
717	        }
718	        else {
719	            indicator.attr(indicatorNewProps);
720	            indicatorLabel.attr(labelNewProps);
721	        }
722	
723	        this._firstShowIndicator = false;
724	
725	        const handleLabels = this._shapes.handleLabels;
726	        if (handleLabels) {
727	            for (let i = 0; i < handleLabels.length; i++) {
728	                // Fade out handle labels.
729	                // NOTE: Must use api enter/leave on emphasis/blur/select state. Or the global states manager will change it.
730	                this.api.enterBlur(handleLabels[i]);
731	            }
732	        }
733	    }
734	
735	    private _enableHoverLinkToSeries() {
736	        const self = this;
737	        this._shapes.mainGroup
738	
739	            .on('mousemove', function (e) {
740	                self._hovering = true;
741	
742	                if (!self._dragging) {
743	                    const itemSize = self.visualMapModel.itemSize;
744	                    const pos = self._applyTransform(
745	                        [e.offsetX, e.offsetY], self._shapes.mainGroup, true, true
746	                    );
747	                    // For hover link show when hover handle, which might be
748	                    // below or upper than sizeExtent.
749	                    pos[1] = mathMin(mathMax(0, pos[1]), itemSize[1]);
750	                    self._doHoverLinkToSeries(
751	                        pos[1],
752	                        0 <= pos[0] && pos[0] <= itemSize[0]
753	                    );
754	                }
755	            })
756	
757	            .on('mouseout', function () {
758	                // When mouse is out of handle, hoverLink still need
759	                // to be displayed when realtime is set as false.
760	                self._hovering = false;
761	                !self._dragging && self._clearHoverLinkToSeries();
762	            });
763	    }
764	
765	    private _enableHoverLinkFromSeries() {
766	        const zr = this.api.getZr();
767	
768	        if (this.visualMapModel.option.hoverLink) {
769	            zr.on('mouseover', this._hoverLinkFromSeriesMouseOver, this);
770	            zr.on('mouseout', this._hideIndicator, this);
771	        }
772	        else {
773	            this._clearHoverLinkFromSeries();
774	        }
775	    }
776	
777	    private _doHoverLinkToSeries(cursorPos: number, hoverOnBar?: boolean) {
778	        const visualMapModel = this.visualMapModel;
779	        const itemSize = visualMapModel.itemSize;
780	
781	        if (!visualMapModel.option.hoverLink) {
782	            return;
783	        }
784	
785	        const sizeExtent = [0, itemSize[1]];
786	        const dataExtent = visualMapModel.getExtent();
787	
788	        // For hover link show when hover handle, which might be below or upper than sizeExtent.
789	        cursorPos = mathMin(mathMax(sizeExtent[0], cursorPos), sizeExtent[1]);
790	
791	        const halfHoverLinkSize = getHalfHoverLinkSize(visualMapModel, dataExtent, sizeExtent);
792	        const hoverRange = [cursorPos - halfHoverLinkSize, cursorPos + halfHoverLinkSize];
793	        const cursorValue = linearMap(cursorPos, sizeExtent, dataExtent, true);
794	        const valueRange = [
795	            linearMap(hoverRange[0], sizeExtent, dataExtent, true),
796	            linearMap(hoverRange[1], sizeExtent, dataExtent, true)
797	        ];
798	        // Consider data range is out of visualMap range, see test/visualMap-continuous.html,
799	        // where china and india has very large population.
800	        hoverRange[0] < sizeExtent[0] && (valueRange[0] = -Infinity);
801	        hoverRange[1] > sizeExtent[1] && (valueRange[1] = Infinity);
802	
803	        // Do not show indicator when mouse is over handle,
804	        // otherwise labels overlap, especially when dragging.
805	        if (hoverOnBar) {
806	            if (valueRange[0] === -Infinity) {
807	                this._showIndicator(cursorValue, valueRange[1], '< ', halfHoverLinkSize);
808	            }
809	            else if (valueRange[1] === Infinity) {
810	                this._showIndicator(cursorValue, valueRange[0], '> ', halfHoverLinkSize);
811	            }
812	            else {
813	                this._showIndicator(cursorValue, cursorValue, '≈ ', halfHoverLinkSize);
814	            }
815	        }
816	
817	        // When realtime is set as false, handles, which are in barGroup,
818	        // also trigger hoverLink, which help user to realize where they
819	        // focus on when dragging. (see test/heatmap-large.html)
820	        // When realtime is set as true, highlight will not show when hover
821	        // handle, because the label on handle, which displays a exact value
822	        // but not range, might mislead users.
823	        const oldBatch = this._hoverLinkDataIndices;
824	        let newBatch: TargetDataIndices = [];
825	        if (hoverOnBar || useHoverLinkOnHandle(visualMapModel)) {
826	            newBatch = this._hoverLinkDataIndices = visualMapModel.findTargetDataIndices(valueRange);
827	        }
828	
829	        const resultBatches = modelUtil.compressBatches(oldBatch, newBatch);
830	
831	        this._dispatchHighDown('downplay', helper.makeHighDownBatch(resultBatches[0], visualMapModel));
832	        this._dispatchHighDown('highlight', helper.makeHighDownBatch(resultBatches[1], visualMapModel));
833	    }
834	
835	    private _hoverLinkFromSeriesMouseOver(e: ElementEvent) {
836	        let ecData: ECData;
837	
838	        findEventDispatcher(e.target, target => {
839	            const currECData = getECData(target);
840	            if (currECData.dataIndex != null) {
841	                ecData = currECData;
842	                return true;
843	            }
844	        }, true);
845	
846	        if (!ecData) {
847	            return;
848	        }
849	
850	        const dataModel = this.ecModel.getSeriesByIndex(ecData.seriesIndex);
851	
852	        const visualMapModel = this.visualMapModel;
853	        if (!visualMapModel.isTargetSeries(dataModel)) {
854	            return;
855	        }
856	
857	        const data = dataModel.getData(ecData.dataType);
858	        const value = data.getStore().get(visualMapModel.getDataDimensionIndex(data), ecData.dataIndex) as number;
859	
860	        if (!isNaN(value)) {
861	            this._showIndicator(value, value);
862	        }
863	    }
864	
865	    private _hideIndicator() {
866	        const shapes = this._shapes;
867	        shapes.indicator && shapes.indicator.attr('invisible', true);
868	        shapes.indicatorLabel && shapes.indicatorLabel.attr('invisible', true);
869	
870	        const handleLabels = this._shapes.handleLabels;
871	        if (handleLabels) {
872	            for (let i = 0; i < handleLabels.length; i++) {
873	                // Fade out handle labels.
874	                // NOTE: Must use api enter/leave on emphasis/blur/select state. Or the global states manager will change it.
875	                this.api.leaveBlur(handleLabels[i]);
876	            }
877	        }
878	    }
879	
880	    private _clearHoverLinkToSeries() {
881	        this._hideIndicator();
882	
883	        const indices = this._hoverLinkDataIndices;
884	        this._dispatchHighDown('downplay', helper.makeHighDownBatch(indices, this.visualMapModel));
885	
886	        indices.length = 0;
887	    }
888	
889	    private _clearHoverLinkFromSeries() {
890	        this._hideIndicator();
891	
892	        const zr = this.api.getZr();
893	
894	        zr.off('mouseover', this._hoverLinkFromSeriesMouseOver);
895	        zr.off('mouseout', this._hideIndicator);
896	    }
