949	function getHalfHoverLinkSize(visualMapModel: ContinuousModel, dataExtent: number[], sizeExtent: number[]) {
950	    let halfHoverLinkSize = HOVER_LINK_SIZE / 2;
951	    const hoverLinkDataSize = visualMapModel.get('hoverLinkDataSize');
952	    if (hoverLinkDataSize) {
953	        halfHoverLinkSize = linearMap(hoverLinkDataSize, dataExtent, sizeExtent, true) / 2;
