// Regression test for `visualMap.continuous.unboundedRange`.
// Upstream: apache/echarts PR #21113.
// Run with:
//   npx jest --config test/ut/jest.config.cjs --coverage=false \
//     --roots /workspace/agent_tests/visualmap-unbounded-range --testMatch '**/*.test.ts'

import { createChart, getECModel } from '../../test/ut/core/utHelper';
import { EChartsType } from '../../src/echarts';
import { EChartsOption } from '../../src/export/option';
import ContinuousModel from '../../src/component/visualMap/ContinuousModel';

function getVisualMapModel(chart: EChartsType): ContinuousModel {
    return getECModel(chart).getComponent('visualMap') as unknown as ContinuousModel;
}

describe('visualMap_continuous_unboundedRange', function () {
    let chart: EChartsType;

    afterEach(function () {
        chart && chart.dispose();
    });

    function makeChart(visualMap: Record<string, unknown>) {
        chart = createChart();
        chart.setOption({
            xAxis: {},
            yAxis: {},
            series: [{type: 'scatter', data: [[1, -100], [2, 500], [3, 1020]]}],
            visualMap: {
                type: 'continuous',
                min: 0,
                max: 1000,
                dimension: 1,
                ...visualMap
            }
        } as EChartsOption);
        return getVisualMapModel(chart);
    }

    it('defaults to unbounded (backward compatible)', function () {
        const model = makeChart({});
        // range is [0, 1000], touching both min and max: both sides are open.
        expect(model.getValueState(-100)).toEqual('inRange');
        expect(model.getValueState(500)).toEqual('inRange');
        expect(model.getValueState(1020)).toEqual('inRange');
    });

    it('unboundedRange: true keeps open sides when range touches min/max', function () {
        const model = makeChart({unboundedRange: true});
        expect(model.getValueState(-100)).toEqual('inRange');
        expect(model.getValueState(1020)).toEqual('inRange');
    });

    it('unboundedRange: false treats outliers as outOfRange', function () {
        const model = makeChart({unboundedRange: false});
        expect(model.getValueState(-100)).toEqual('outOfRange');
        expect(model.getValueState(0)).toEqual('inRange');
        expect(model.getValueState(500)).toEqual('inRange');
        expect(model.getValueState(1000)).toEqual('inRange');
        expect(model.getValueState(1020)).toEqual('outOfRange');
    });

    it('range not touching min/max stays bounded on that side', function () {
        const model = makeChart({range: [100, 500]});
        expect(model.getValueState(50)).toEqual('outOfRange');
        expect(model.getValueState(600)).toEqual('outOfRange');
        expect(model.getValueState(300)).toEqual('inRange');
    });

    it('unboundedRange: false with inner range behaves the same', function () {
        const model = makeChart({range: [100, 500], unboundedRange: false});
        expect(model.getValueState(50)).toEqual('outOfRange');
        expect(model.getValueState(600)).toEqual('outOfRange');
        expect(model.getValueState(300)).toEqual('inRange');
    });

    it('unboundedRange applies per side when only one side touches', function () {
        // range [0, 500]: lower side open, upper side bounded.
        const model = makeChart({range: [0, 500]});
        expect(model.getValueState(-100)).toEqual('inRange');
        expect(model.getValueState(600)).toEqual('outOfRange');
        // range [500, 1000]: upper side open, lower side bounded.
        const model2 = makeChart({range: [500, 1000]});
        expect(model2.getValueState(1020)).toEqual('inRange');
        expect(model2.getValueState(300)).toEqual('outOfRange');
    });
});
